contract InvMutTest {
    C c;
    bool private refuseEther;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(bool shouldRefuse) public payable {
        refuseEther = shouldRefuse;

        bool reverted;
        c.withdrawReward(address(this)); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(shouldRefuse ? reverted : !reverted);
    }

    receive() external payable {
        require(!refuseEther);
    }
}

