// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrancy_bonus c;
    bool private refuseEther;

    function setUp() public {
        c = new Reentrancy_bonus();
    }

    function _run(bool shouldRefuse) internal {
        refuseEther = shouldRefuse;
        bool reverted;
        try c.withdrawReward(address(this)) { reverted = false; } catch { reverted = true; }
        assertTrue(shouldRefuse ? reverted : !reverted);
    }

    function testFuzz_run(bool shouldRefuse) public {
        _run(shouldRefuse);
    }

    receive() external payable {
        require(!refuseEther);
    }
}
